    const sortedKeys = Array.from(allKeysSet).sort();

    const matrix = [sortedKeys];
    for (const map of keyMaps) {
        const row = sortedKeys.map(k => (k in map ? map[k] : ''));
        matrix.push(row);
    }
    return matrix;
};
